// Hoenn & Seek: where Hoenn & Seek's flags and vars are stored.
//
// HnS keeps its own flags in SaveBlock1, which is full. Hoenn & Seek's flags
// and vars live in SaveBlock3 instead, in two generations:
//
//   1.0  hoennFlags / hoennVars             Emerald's flags for the Hoenn maps,
//                                           generated by tools/hoenn/gen_hoenn_ids.py
//   2.0  hoennEventFlags / hoennEventVars   hand-defined flags for 2.0's events,
//                                           allocated by phase in constants/hoenn_events.h
//
// The ID ranges are documented in constants/hoenn_layout.h. GetFlagPointer and
// GetVarPointer (src/event_data.c) call the two functions below for any Hoenn
// ID, so scripts use setflag/setvar on these like on any other flag or var.

#include "global.h"
#include "event_data.h"
#include "hoenn_flags.h"
#include "constants/flags.h"
#include "constants/vars.h"
#include "constants/hoenn_events.h"

#if IS_HNS

// ---- Build-time checks --------------------------------------------------

// The emulator harness (tools/hoenn/emu/pt.py) pokes these arrays at fixed
// offsets into SaveBlock3. If one of these fails, a field was added in front
// of them: update HOENN_*_SB3 in pt.py to the new offsets.
STATIC_ASSERT(offsetof(struct SaveBlock3, hoennFlags) == 0x32, HoennHarnessFlagsOffset);
STATIC_ASSERT(offsetof(struct SaveBlock3, hoennVars) == 0x132, HoennHarnessVarsOffset);
STATIC_ASSERT(offsetof(struct SaveBlock3, hoennEventFlags) == 0x232, HoennHarnessEventFlagsOffset);
STATIC_ASSERT(offsetof(struct SaveBlock3, hoennEventVars) == 0x2B2, HoennHarnessEventVarsOffset);

// The 2.0 ranges must not overlap anything else.
STATIC_ASSERT(HOENN_EVENT_FLAGS_START == HOENN_FLAGS_END + 1, HoennEventFlagsFollow1_0);
STATIC_ASSERT(HOENN_EVENT_FLAGS_END < SPECIAL_FLAGS_START, HoennEventFlagsBelowSpecialFlags);
STATIC_ASSERT(HOENN_EVENT_VARS_START + HOENN_EVENT_VARS_COUNT <= SPECIAL_VARS_START, HoennEventVarsBelowSpecialVars);
// Hidden items store their flag as a 13-bit offset from FLAG_HIDDEN_ITEMS_START.
STATIC_ASSERT(HOENN_EVENT_HIDDEN_ITEMS_START + 64 - 1 - FLAG_HIDDEN_ITEMS_START < (1 << 13), HoennEventHiddenItemsFit);

// The phase blocks in constants/hoenn_events.h must be in order, end to end,
// and stay inside 0x2040-0x22FF. Each block ends where the next one starts.
#define BLOCK_ORDER(a, b) STATIC_ASSERT((a) < (b), HoennFlagBlockOrder_##a##_##b)
STATIC_ASSERT(HOENN_FLAGS_A_FOUNDATIONS == HOENN_EVENT_BLOCKS_START, HoennFirstFlagBlock);
BLOCK_ORDER(HOENN_FLAGS_A_FOUNDATIONS,   HOENN_FLAGS_B_WEATHER_HINTS);
BLOCK_ORDER(HOENN_FLAGS_B_WEATHER_HINTS, HOENN_FLAGS_C_BUILDINGS);
BLOCK_ORDER(HOENN_FLAGS_C_BUILDINGS,     HOENN_FLAGS_C_WORLD);
BLOCK_ORDER(HOENN_FLAGS_C_WORLD,         HOENN_FLAGS_D_STARTERS);
BLOCK_ORDER(HOENN_FLAGS_D_STARTERS,      HOENN_FLAGS_D_SPECIES);
BLOCK_ORDER(HOENN_FLAGS_D_SPECIES,       HOENN_FLAGS_E_HOENN);
BLOCK_ORDER(HOENN_FLAGS_E_HOENN,         HOENN_FLAGS_E_JOHTO_KANTO);
BLOCK_ORDER(HOENN_FLAGS_E_JOHTO_KANTO,   HOENN_FLAGS_F_LEGENDARIES);
BLOCK_ORDER(HOENN_FLAGS_F_LEGENDARIES,   HOENN_FLAGS_G_FINISH);
BLOCK_ORDER(HOENN_FLAGS_G_FINISH,        HOENN_FLAGS_SPARE);
BLOCK_ORDER(HOENN_FLAGS_SPARE,           HOENN_FLAGS_BLOCKS_END);
STATIC_ASSERT(HOENN_FLAGS_BLOCKS_END == HOENN_DAILY_FLAGS_START, HoennFlagBlocksEndAtDaily);
STATIC_ASSERT(HOENN_DAILY_FLAGS_END + 1 == HOENN_WEEKLY_FLAGS_START, HoennWeeklyFollowsDaily);
STATIC_ASSERT(HOENN_WEEKLY_FLAGS_END < HOENN_EVENT_FLAGS_END, HoennWeeklyInsideRange);

STATIC_ASSERT(HOENN_VARS_A_FOUNDATIONS == HOENN_EVENT_VARS_START, HoennFirstVarBlock);
BLOCK_ORDER(HOENN_VARS_A_FOUNDATIONS,   HOENN_VARS_B_WEATHER_HINTS);
BLOCK_ORDER(HOENN_VARS_B_WEATHER_HINTS, HOENN_VARS_C_WORLD);
BLOCK_ORDER(HOENN_VARS_C_WORLD,         HOENN_VARS_D_EVENTS);
BLOCK_ORDER(HOENN_VARS_D_EVENTS,        HOENN_VARS_E_EVENTS);
BLOCK_ORDER(HOENN_VARS_E_EVENTS,        HOENN_VARS_F_LEGENDARIES);
BLOCK_ORDER(HOENN_VARS_F_LEGENDARIES,   HOENN_VARS_G_FINISH);
BLOCK_ORDER(HOENN_VARS_G_FINISH,        HOENN_VARS_SPARE);
BLOCK_ORDER(HOENN_VARS_SPARE,           HOENN_VARS_BLOCKS_END);
#undef BLOCK_ORDER

// The two builder lanes' ranges (lane setup, Nov 27; constants/hoenn_events.h):
// each inside its block or reset range, lane A's before lane B's, no overlap.
#define LANE_FITS(start, count, lo, hi) \
    STATIC_ASSERT((start) >= (lo) && (start) + (count) <= (hi), HoennLaneRange_##start)
LANE_FITS(HOENN_LANE_A_FLAGS_E, HOENN_LANE_A_FLAGS_E_COUNT, HOENN_FLAGS_E_JOHTO_KANTO, HOENN_LANE_B_FLAGS_E);
LANE_FITS(HOENN_LANE_B_FLAGS_E, HOENN_LANE_B_FLAGS_E_COUNT, HOENN_LANE_A_FLAGS_E + HOENN_LANE_A_FLAGS_E_COUNT, HOENN_FLAGS_F_LEGENDARIES);
LANE_FITS(HOENN_LANE_A_FLAGS_F, HOENN_LANE_A_FLAGS_F_COUNT, HOENN_FLAGS_F_LEGENDARIES, HOENN_LANE_B_FLAGS_F);
LANE_FITS(HOENN_LANE_B_FLAGS_F, HOENN_LANE_B_FLAGS_F_COUNT, HOENN_LANE_A_FLAGS_F + HOENN_LANE_A_FLAGS_F_COUNT, HOENN_FLAGS_G_FINISH);
LANE_FITS(HOENN_LANE_A_DAILY, HOENN_LANE_A_DAILY_COUNT, HOENN_DAILY_FLAGS_START, HOENN_LANE_B_DAILY);
LANE_FITS(HOENN_LANE_B_DAILY, HOENN_LANE_B_DAILY_COUNT, HOENN_LANE_A_DAILY + HOENN_LANE_A_DAILY_COUNT, HOENN_DAILY_FLAGS_END + 1);
LANE_FITS(HOENN_LANE_A_WEEKLY, HOENN_LANE_A_WEEKLY_COUNT, HOENN_WEEKLY_FLAGS_START, HOENN_LANE_B_WEEKLY);
LANE_FITS(HOENN_LANE_B_WEEKLY, HOENN_LANE_B_WEEKLY_COUNT, HOENN_LANE_A_WEEKLY + HOENN_LANE_A_WEEKLY_COUNT, HOENN_WEEKLY_FLAGS_END + 1);
LANE_FITS(HOENN_LANE_A_HIDDEN, HOENN_LANE_A_HIDDEN_COUNT, HOENN_EVENT_HIDDEN_ITEMS_START, HOENN_LANE_B_HIDDEN);
LANE_FITS(HOENN_LANE_B_HIDDEN, HOENN_LANE_B_HIDDEN_COUNT, HOENN_LANE_A_HIDDEN + HOENN_LANE_A_HIDDEN_COUNT, HOENN_EVENT_HIDDEN_ITEMS_START + 64);
LANE_FITS(HOENN_LANE_A_VARS_E, HOENN_LANE_A_VARS_E_COUNT, HOENN_VARS_E_EVENTS, HOENN_LANE_B_VARS_E);
LANE_FITS(HOENN_LANE_B_VARS_E, HOENN_LANE_B_VARS_E_COUNT, HOENN_LANE_A_VARS_E + HOENN_LANE_A_VARS_E_COUNT, HOENN_VARS_F_LEGENDARIES);
LANE_FITS(HOENN_LANE_A_VARS_F, HOENN_LANE_A_VARS_F_COUNT, HOENN_VARS_F_LEGENDARIES, HOENN_LANE_B_VARS_F);
LANE_FITS(HOENN_LANE_B_VARS_F, HOENN_LANE_B_VARS_F_COUNT, HOENN_LANE_A_VARS_F + HOENN_LANE_A_VARS_F_COUNT, HOENN_VARS_G_FINISH);
#undef LANE_FITS

// ---- Lookups (called from GetFlagPointer / GetVarPointer) ---------------

// The byte holding a Hoenn flag. Only call it when IS_HOENN_FLAG(id).
u8 *HoennGetFlagPointer(u16 id)
{
    if (IS_HOENN_EVENT_FLAG(id))
        return &gSaveBlock3Ptr->hoennEventFlags[(id - HOENN_EVENT_FLAGS_START) / 8];
    return &gSaveBlock3Ptr->hoennFlags[(id - HOENN_FLAGS_START) / 8];
}

// A Hoenn var. Only call it when IS_HOENN_VAR(id).
u16 *HoennGetVarPointer(u16 id)
{
    if (IS_HOENN_EVENT_VAR(id))
        return &gSaveBlock3Ptr->hoennEventVars[id - HOENN_EVENT_VARS_START];
    return &gSaveBlock3Ptr->hoennVars[id - HOENN_VARS_START];
}

// ---- Resets -------------------------------------------------------------

// New game: every Hoenn & Seek flag and var starts cleared. NewGameInitData
// runs Hoenn's post-Emerald state script (EventScript_ResetAllMapFlagsHoenn)
// right after this.
void HoennClearAllFlagsAndVars(void)
{
    memset(gSaveBlock3Ptr->hoennFlags, 0, sizeof(gSaveBlock3Ptr->hoennFlags));
    memset(gSaveBlock3Ptr->hoennVars, 0, sizeof(gSaveBlock3Ptr->hoennVars));
    HoennClearEventFlagsAndVars();
}

// Just the 2.0 arrays. Also used by the save version 6 upgrade: a 1.0 save
// never wrote this part of SaveBlock3, so it may hold leftover bytes.
void HoennClearEventFlagsAndVars(void)
{
    memset(gSaveBlock3Ptr->hoennEventFlags, 0, sizeof(gSaveBlock3Ptr->hoennEventFlags));
    memset(gSaveBlock3Ptr->hoennEventVars, 0, sizeof(gSaveBlock3Ptr->hoennEventVars));
}

// Runs with HnS's ClearDailyFlags (once a day, when the RTC day changes).
void HoennClearDailyFlags(void)
{
    u32 i;
    for (i = HOENN_DAILY_FLAGS_START; i <= HOENN_DAILY_FLAGS_END; i++)
        FlagClear(i);
}

// Weekly flags: HOENN_WEEKLY_FLAGS_START-END. Part 2 clears them at the start
// of each in-game week, once the weekday system exists.
void HoennClearWeeklyFlags(void)
{
    u32 i;
    for (i = HOENN_WEEKLY_FLAGS_START; i <= HOENN_WEEKLY_FLAGS_END; i++)
        FlagClear(i);
}

#endif // IS_HNS
